(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  let changed = 0;
  document.querySelectorAll('div,section,main,aside').forEach(e => {
    if (e.scrollHeight > e.clientHeight + 50 && e.clientHeight > 150) { e.scrollTop = 0; changed++; }
  });
  window.scrollTo(0,0);
  document.scrollingElement && (document.scrollingElement.scrollTop = 0);
  await sleep(1500);
  const boxes = Array.from(document.querySelectorAll('input[type=number]')).filter(i=>i.offsetParent!==null && /^(first|second|third|fourth|fifth|sixth)$/.test(i.id||'')).map(i => i.id + '=' + i.value);
  const cfm = Array.from(document.querySelectorAll('button')).filter(b=>/confirm\s*otp/i.test((b.innerText||'').replace(/\s+/g,' '))).map(b=>({v:(b.innerText||'').replace(/\s+/g,' ').trim(), vis:b.offsetParent!==null}));
  return JSON.stringify({changed, boxes, cfm});
})()
